def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])

    # Lattice separators are nearly uniform rows or columns. Allow for
    # occasional colored marks where the separator lines cross.
    row_lines = []
    for r, row in enumerate(grid):
        counts = Counter(row)
        if counts.most_common(1)[0][1] >= w - 2:
            row_lines.append(r)

    col_lines = []
    for c in range(w):
        counts = Counter(grid[r][c] for r in range(h))
        if counts.most_common(1)[0][1] >= h - 2:
            col_lines.append(c)

    def infer_step(lines):
        gaps = [b - a for a, b in zip(lines, lines[1:])]
        return Counter(gaps).most_common(1)[0][0] if gaps else 1

    def regularize(lines, limit):
        if not lines:
            return []
        step = infer_step(lines)
        start = lines[0]
        return list(range(start, limit, step))

    row_lines = regularize(row_lines, h)
    col_lines = regularize(col_lines, w)
    if len(row_lines) < 2 or len(col_lines) < 2:
        return [[0]]

    line_colors = set()
    for r in row_lines:
        line_colors.add(Counter(grid[r]).most_common(1)[0][0])
    for c in col_lines:
        line_colors.add(Counter(grid[r][c] for r in range(h)).most_common(1)[0][0])

    interior = Counter(
        grid[r][c]
        for r in range(h) for c in range(w)
        if r not in row_lines and c not in col_lines
    )
    fill = interior.most_common(1)[0][0] if interior else 0

    out = [[fill for _ in range(len(col_lines) - 1)]
           for _ in range(len(row_lines) - 1)]
    for i, r in enumerate(row_lines[:-1]):
        for j, c in enumerate(col_lines[:-1]):
            value = grid[r][c]
            if value != fill and value not in line_colors:
                out[i][j] = value
            elif value != fill and value != 0:
                # Colored marks on separator intersections encode output cells.
                out[i][j] = value
    return out
